-- Ejecutar SOLO contra una base Supabase local/aislada después de aplicar todas
-- las migraciones. Todo queda dentro de una transacción y termina en ROLLBACK.
BEGIN;




VALUES ('40000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000001', 'Coach A', '10000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000003');


VALUES ('60000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000001', '40000000-0000-0000-0000-000000000001');








-- Comunicación: una fila local por academia y una plantilla global de sistema.



-- Catálogos globales: lectura autenticada, nunca anónima ni mutación browser.
VALUES ('96000000-0000-0000-0000-000000000001', 'ZZ', 'Fixture country');

-- Owner A: CRUD local permitido, academia B invisible.

-- Synthetic academy-scoped admin; no real identities or production records.
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000009',true);
DO $$ DECLARE affected integer; BEGIN
  IF (SELECT count(*) FROM public.charges) <> 2 THEN RAISE EXCEPTION 'admin crossed academy boundary on SELECT'; END IF;
  UPDATE public.charges SET label='not allowed' WHERE id='95000000-0000-0000-0000-000000000003';
  GET DIAGNOSTICS affected=ROW_COUNT;
  IF affected <> 0 THEN RAISE EXCEPTION 'admin crossed academy boundary on UPDATE'; END IF;
  DELETE FROM public.charges WHERE id='95000000-0000-0000-0000-000000000003';
  GET DIAGNOSTICS affected=ROW_COUNT;
  IF affected <> 0 THEN RAISE EXCEPTION 'admin crossed academy boundary on DELETE'; END IF;
  BEGIN
    RAISE EXCEPTION 'admin crossed academy boundary on INSERT';
  EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  UPDATE public.charges SET label='allowed local update' WHERE id='95000000-0000-0000-0000-000000000001';
  GET DIAGNOSTICS affected=ROW_COUNT;
  IF affected <> 1 THEN RAISE EXCEPTION 'scoped admin lost own academy write'; END IF;
END $$;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
DO $$ BEGIN
  IF (SELECT count(*) FROM public.charges) <> 1 THEN RAISE EXCEPTION 'linked parent billing regression'; END IF;
END $$;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000008',true);
DO $$ BEGIN
  IF (SELECT count(*) FROM public.charges) <> 3 THEN RAISE EXCEPTION 'super-admin billing regression'; END IF;
END $$;
RESET ROLE;
ROLLBACK;
